// Network facts that change rarely: joining rules and pay terms, with sources.
// The page shows these numbers; the MDX words never repeat them. Use null for
// anything the network does not publish, and the page shows "Not public".

export type AdNetworkKeyNumber = {
  label: string; // "Sessions to join", "Your share", "Paid"
  value: string; // "50,000", "75%", "Net 65"
  note?: string; // "a month", "of ad revenue"
  sourceUrl: string;
};

export type AdNetworkFacts = {
  checkedAt: string; // YYYY-MM-DD, the day the sources were read
  keyNumbers: AdNetworkKeyNumber[]; // up to three, most useful first
  joining: { label: string; value: string; note?: string; sourceUrl: string | null }[];
  // Monthly, for sorting by how easy a network is to join. 0 only when the network says it has no
  // minimum; null when it publishes none. `label` keeps the network's own wording, such as
  // "More than 100,000 visits a month", wherever the rule is shown.
  minTraffic: { amount: number; unit: "sessions" | "pageviews" | "visitors"; label?: string } | null;
  revenueShare: string | null;
  paymentTerms: string | null;
  paymentThreshold: string | null;
  paymentMethods: string[];
  sources: { label: string; url: string }[];
};

